import importlib.util
for n in ['numpy', 'scipy', 'matplotlib']:
 print(n, bool(importlib.util.find_spec(n)))
from fractions import Fraction as F
beta=F(1,2)
a,b,c,d=F(2,5),F(2,5),F(1,5),F(1,5)
def eta(x,y):
 return 1-y/x if y<x else (1-(1-y)/(1-x) if y>x else F(0))
def psi(x):
 return beta*eta(a+b*x,c+d*x)+(1-beta)*(1-c-d*x)
