from fractions import Fraction as Q

def eta(a,b):
 if a==b: return 0.0
 if b<a: return 1-b/a
 return 1-(1-b)/(1-a)
def uf_two(a,b,wa,wb):
 return min(wa*eta(t,a)+wb*eta(t,b) for t in (0.0,1.0,a,b))
front=[]
N=400
for i in range(N+1):
 x=.25+.5*i/N
 for j in range(N+1):
  y=j/N
  e=2*x/3+y/3-1/12
  if e>.251: continue
  u=uf_two(x,y,1/3,1/6)+uf_two(2*x-.5,.5*y,1/6,1/3)
  front.append((u,e,x,y))
for lim in [.02,.04,.06]:
 p=min((p for p in front if p[0]<=lim),key=lambda p:p[1])
 print('Fig. 1 grid: constraint',lim,'best (unfairness,error,FPR_L,FPR_R)',p)
for beta in [.5,.6,2/3,.7,.8]:
 p=min(front,key=lambda p:beta*p[0]+(1-beta)*p[1])
 print('Fig. 1 grid: beta',beta,'weighted-sum minimizer',p)
